\label{thm:classification}
Under \eqref{eq:weighted-setting}, the exponent $D_G(T,o)$ is
independent of $o$, takes values in $[0,2]$, and satisfies
\begin{equation}
 \widetilde\alpha_{\mathsf c}(T)=1-\frac{D_G(T,o)}2
       =1-\frac12\dim_{\mathrm H}(\partial T,\delta_G).
 \label{eq:classification}
\end{equation}
The exponent is also independent of the choice of a locally finite
weighted skeleton representing the same cable tree. At intensity one,
the whole cable tree is almost surely a single cluster.

\label{thm:half-analytic}
Suppose \eqref{eq:weighted-setting} and \eqref{eq:capacity-condition}
hold. Then $D_G(T)\le1$, $\widetilde\alpha_{\mathsf c}(T)\ge1/2$, and all clusters at
intensity $1/2$ are bounded almost surely. Moreover,
\begin{equation}
 \widetilde\alpha_{\mathsf c}(T)=\frac12\quad\Longleftrightarrow\quad
 \inf_{\Pi\in\mathcal C_o}\sum_{x\in\Pi}\rho_o(x)^s>0
       \quad\text{for every }0<s<1.
 \label{eq:half-condition}
\end{equation}
Equivalently, for every $0<\beta<1$, the network with edge
resistances
\begin{equation}
 r_\beta(x)=\rho_o(x)^{-\beta}-\rho_o(x^-)^{-\beta}
          \quad(x\ne o)
 \label{eq:analytic-resistances}
\end{equation}
is transient. A sufficient condition for these equivalent conclusions
is that a set of rays of positive harmonic measure satisfies
\begin{equation}
 \frac{\log^+\Lambda(\xi_n)}{\log(1/\theta(\xi_n))}
                  \longrightarrow0.
 \label{eq:analytic-ray-condition}
\end{equation}

\label{cor:symmetric}
Suppose all conductances are one and every vertex at depth $n$ has
$b_n$ children, where $b_0\ge3$ and $b_n\ge2$ for $n\ge1$. Define
\begin{equation}
 N_0=1,\qquad N_{n+1}=N_nb_n,\qquad
 r=\limsup_{n\to\infty}\frac{\log b_n}{\log N_n}\in[0,\infty].
 \label{eq:symmetric-parameters}
\end{equation}
Then
\begin{equation}
 D_G(T)=\frac2{2+r},\qquad
 \widetilde\alpha_{\mathsf c}(T)=\frac{1+r}{2+r},
 \label{eq:symmetric}
\end{equation}
with $D_G(T)=0$ and $\widetilde\alpha_{\mathsf c}(T)=1$ when $r=\infty$.

\label{cor:fixed-branching}
For every $a\in[1/2,1]$, there is a spherically symmetric tree
with unit conductances and minimum degree three such that
\begin{equation}
 \operatorname{br}(T)=2,\qquad \widetilde\alpha_{\mathsf c}(T)=a.
 \label{eq:fixed-branching}
\end{equation}

\label{prop:weighted-example}
Fix an integer $b\ge2$. Give the root $b+1$ children and every
other vertex $b$ children. For $1/b<a\le1$, put conductance $a^n$
on each edge from generation $n$ to generation $n+1$. Then
\eqref{eq:weighted-setting} holds and
\begin{equation}
 D_G(T)=\frac{2\log b}{\log(b^2a)},\qquad
 \widetilde\alpha_{\mathsf c}(T)=\frac{\log(ba)}{\log(b^2a)}.
 \label{eq:weighted-example}
\end{equation}

\label{prop:zero-threshold}
Start from the rooted binary tree and replace every edge between
generations $n$ and $n+1$ by
\begin{equation}
 L_n=\left\lceil\frac{2^n}{(n+1)^2}\right\rceil,
 \qquad n\ge0,
 \label{eq:zero-threshold-lengths}
\end{equation}
unit-conductance edges in series. The resulting tree $T$ has maximum
degree three, satisfies \eqref{eq:weighted-setting}, and has
\begin{equation}
 D_G(T)=2,\qquad \widetilde\alpha_{\mathsf c}(T)=0.
 \label{eq:zero-threshold}
\end{equation}

\label{cor:gff-separation}
Under \eqref{eq:weighted-setting} and \eqref{eq:capacity-condition},
$\widetilde h_*(T)=0$.

\label{thm:GW}
For $\mathbf P(\,\cdot\mid\mathsf S)$-almost every $T$, the tree is
transient and
\begin{equation}
 D_G(T)=1,\qquad \widetilde\alpha_{\mathsf c}(T)=\frac12.
 \label{eq:GW}
\end{equation}
On each such tree there is no percolation at intensity $1/2$, and
the root has positive probability of percolating at every
$\alpha>1/2$.

\label{cor:real-tree}
Suppose $\mathcal T$ is proper, is spanned by its infinite rays,
and its Brownian motion with length measure is transient, with no
killing. Then $D_G(\mathcal T,o)$ is independent of the root and
\begin{equation}
 0\le D_G(\mathcal T,o)\le2,\qquad
 \widetilde\alpha_{\mathsf c}(\mathcal T)=1-\frac{D_G(\mathcal T,o)}2.
 \label{eq:real-tree-classification}
\end{equation}
At intensity one the whole tree is almost surely a single cluster.

\label{lem:green-transform}
Set $g_o=g(o,o)$ and
\begin{equation}
 h(x)=\frac{g(o,x)}{g_o}=H(x,o),\qquad
 \widehat c_{xy}=c_{xy}h(x)h(y).
 \label{eq:green-transform}
\end{equation}
The network $(T,\widehat c)$ is recurrent. For every vertex $x$,
\begin{equation}
 \rho_o(x)^{-2}
 =1+\frac1{g_o}\sum_{e\in[o,x]}\frac1{\widehat c_e}.
 \label{eq:green-resistance}
\end{equation}
In particular,
\begin{equation}
 \rho_o(\xi_n)\downarrow0\qquad\text{for every }\xi\in\partial T.
 \label{eq:ray-correlation-decay}
\end{equation}

\label{lem:branching}
For any cable point $a$, conditional on $X(a)$, the fields in the components of
$\widetilde T\setminus\{a\}$ are independent. Along a geodesic directed
away from $a$, with parameter $t=-\log\rho(a,\cdot)^2$, the field
has the law of the stationary diffusion, restricted to the range of
this parameter,
\begin{equation}
 dX_t=\sqrt{2X_t}\,dB_t+(\alpha-X_t)\,dt,\qquad
 X_0\sim\operatorname{Gamma}(\alpha,1).
 \label{eq:CIR}
\end{equation}
Here $B$ is a standard one-dimensional Brownian motion, independent
of $X_0$.

\label{prop:two-point}
Let $u\ne v$ be cable points and $0<\alpha<1$. Then
\begin{equation}
 p_\alpha(u,v)=I_{\rho(u,v)^2}(1-\alpha,\alpha).
 \label{eq:beta}
\end{equation}
More precisely, for $q=\rho(u,v)^2$ and $z>0$,
\begin{equation}
 \mathbb P_\alpha^T(u\leftrightarrow v\mid X(u)=z)
 =F_{\alpha,q}(z):=\frac1{\Gamma(1-\alpha)}
       \int_0^{zq/(1-q)}r^{-\alpha}e^{-r}\,dr.
 \label{eq:conditional-connection}
\end{equation}
With $F_{\alpha,q}(0)=0$, this function is nonnegative, increasing
and concave on $[0,\infty)$. If
$\beta=2(1-\alpha)$, there are constants
$0<c_\alpha\le C_\alpha<\infty$, depending only on $\alpha$, such that
\begin{equation}
 c_\alpha\rho(u,v)^\beta\le p_\alpha(u,v)
 \le C_\alpha\rho(u,v)^\beta.
 \label{eq:power}
\end{equation}
The bounds in \eqref{eq:power} also hold for $u=v$. For $\alpha\ge1$,
\begin{equation}
 \mathbb P_\alpha^T(\widetilde T\text{ is a single loop cluster})=1.
 \label{eq:full-connection}
\end{equation}

\label{lem:concavity}
Let $\alpha>0$ and let $k\ge1$ be an integer. If
$Z\sim\operatorname{Gamma}(\alpha,1)$ and $f_1,\ldots,f_k$ are bounded
nonnegative increasing concave functions on $[0,\infty)$, then
\begin{equation}
 \mathbb E\prod_{i=1}^k f_i(Z)
 \le\frac{\mathbb E Z^k}{(\mathbb E Z)^k}\prod_{i=1}^k\mathbb E f_i(Z).
 \label{eq:concavity}
\end{equation}

\label{prop:quasi}
Let $0<\alpha<1$ and write $p(x)=p_\alpha(o,x)$ for $x\in V$.
For $x,y\in V$ and $a=x\wedge y$,
\begin{equation}
 \mathbb P_\alpha^T(o\leftrightarrow x,\ o\leftrightarrow y)
 \le K_\alpha\frac{p(x)p(y)}{p(a)},\qquad
 K_\alpha=\frac{(\alpha+1)(\alpha+2)}{\alpha^2}.
 \label{eq:quasi}
\end{equation}

\label{lem:capacity-criterion}
Let $0<\alpha<1$ and $\beta=2(1-\alpha)$. If
\begin{equation}
 \inf_\Pi\sum_{x\in\Pi}\rho_o(x)^\beta=0,
 \label{eq:zero-cutset-sum}
\end{equation}
there is almost surely no unbounded cluster.
If $\mathcal E_\beta(\mu)<\infty$ for some unit
flow, then
\begin{equation}
 \mathbb P_\alpha^T(o\leftrightarrow\infty)
 \ge \frac{c_\alpha}{K_\alpha\mathcal E_\beta(\mu)}>0.
 \label{eq:survival}
\end{equation}

An infinite root cluster contains a ray and so meets every cutset.
The union bound and \eqref{eq:power} imply
\begin{equation}
 \mathbb P_\alpha^T(o\leftrightarrow\infty)
 \le C_\alpha\sum_{x\in\Pi}\rho_o(x)^\beta.
 \label{eq:cutset-first-moment}
\end{equation}
Under \eqref{eq:zero-cutset-sum}, taking the infimum in
\eqref{eq:cutset-first-moment} proves that the root cluster is bounded
almost surely.
Every unbounded cluster contains a vertex. If one occurred with
positive probability, countability would give a fixed vertex $u$
with positive probability of belonging to one. The events
$\{o\leftrightarrow u\}$ and $\{u\leftrightarrow\infty\}$ are
increasing in the Poisson soup, and are positively associated.
The Poisson Harris inequality gives
\begin{equation}
 \mathbb P_\alpha^T(o\leftrightarrow\infty)
 \ge p_\alpha(o,u)\mathbb P_\alpha^T(u\leftrightarrow\infty).
 \label{eq:root-transfer}
\end{equation}
Since $p_\alpha(o,u)>0$, \eqref{eq:root-transfer} rules out an
unbounded cluster at any fixed vertex, and hence anywhere in $\widetilde T$.

To prove \eqref{eq:survival}, we give the weighted second-moment
argument directly; see~\cite[Section~5.3 and Theorem~5.19]{LP}.
Fix a unit flow $\mu$ with $\mathcal E_\beta(\mu)<\infty$ and set
\begin{equation}
 Z_n=\sum_{|x|=n}\frac{\mu(x)}{p_\alpha(o,x)}
             \mathbf 1_{\{o\leftrightarrow x\}}.
 \label{eq:weighted-connection-count}
\end{equation}
Flow conservation gives $\mathbb E_\alpha^T Z_n=1$. By
\eqref{eq:quasi} and \eqref{eq:power},
\begin{equation}
 \begin{aligned}
 \mathbb E_\alpha^T[Z_n^2]
 &\le K_\alpha\sum_{|x|=|y|=n}
       \frac{\mu(x)\mu(y)}{p_\alpha(o,x\wedge y)}\\
 &\le\frac{K_\alpha}{c_\alpha}
       \sum_{|x|=|y|=n}\mu(x)\mu(y)\rho_o(x\wedge y)^{-\beta}
 \le\frac{K_\alpha}{c_\alpha}\mathcal E_\beta(\mu).
 \end{aligned}
 \label{eq:connection-second-moment}
\end{equation}
For the last inequality, if $\xi\in\partial T_x$ and
$\eta\in\partial T_y$, then
$\delta_G(\xi,\eta)\le\rho_o(x\wedge y)$. This also holds when
$x=y$, so the diagonal terms are included in the energy bound.
Let $A_n$ be the event that the root cluster meets generation $n$.
Since $\{Z_n>0\}\subseteq A_n$, Cauchy--Schwarz gives
\begin{equation}
 \mathbb P_\alpha^T(A_n)\ge\mathbb P_\alpha^T(Z_n>0)
 \ge\frac{(\mathbb E_\alpha^T Z_n)^2}{\mathbb E_\alpha^T[Z_n^2]}
 \ge\frac{c_\alpha}{K_\alpha\mathcal E_\beta(\mu)}.
 \label{eq:generation-second-moment}
\end{equation}
By connectedness, local finiteness and properness, the events $A_n$
decrease to $\{o\leftrightarrow\infty\}$. Letting $n\to\infty$
proves \eqref{eq:survival}.

\label{lem:frostman}
Under \eqref{eq:weighted-setting}, $\delta_G$ is an ultrametric
inducing the compact cylinder topology on $\partial T$, and
\eqref{eq:green-boundary-dimension} holds. If $0<\beta<s<D_G$,
there is a unit flow $\mu$ such that
\begin{equation}
 \mathcal E_\beta(\mu)\le1+\delta^{-1}\frac{\beta}{s-\beta},
 \qquad \delta=\inf_\Pi\sum_{x\in\Pi}\rho_o(x)^s>0.
 \label{eq:frostman}
\end{equation}

\label{lem:point-cutsets}
On a cable tree satisfying \eqref{eq:weighted-setting}, let
$\mathcal C_o^{\mathrm{pt}}$ be the finite point cutsets of its
infinite rays. For every $s\ge0$,
\begin{equation}
 \inf_{\Pi\in\mathcal C_o^{\mathrm{pt}}}\sum_{x\in\Pi}\rho_o(x)^s
 =\inf_{\Pi\in\mathcal C_o}\sum_{x\in\Pi}\rho_o(x)^s.
 \label{eq:point-cutsets}
\end{equation}
Consequently $D_G$ is independent of the weighted skeleton.

Every cable has length at least $1/2$, so the metric is proper.
The electrical unit flow splits equally between descendants, and
its potential at generation $n$ is
\begin{equation}
 V_n=\frac1{b+1}\sum_{k=n}^\infty(ba)^{-k}
     =g_o(ba)^{-n},\qquad g_o=\frac{ba}{(b+1)(ba-1)}<\infty.
 \label{eq:geometric-potential}
\end{equation}
The convergent series of level resistances in \eqref{eq:geometric-potential}
also proves transience.
Consequently $h(x)=(ba)^{-n}$ for $|x|=n$. Equation
\eqref{eq:green-resistance} gives the exact identity
\begin{equation}
 \rho_n^{-2}
 =1+(b+1)(ba-1)\frac{(b^2a)^n-1}{b^2a-1}.
 \label{eq:geometric-correlation}
\end{equation}
Hence $\rho_n\asymp(b\sqrt a)^{-n}$. Since
$N_n=(b+1)b^{n-1}$ for $n\ge1$, equation
\eqref{eq:spherical-cutsets} proves the formula for $D_G$ in
\eqref{eq:weighted-example}; \eqref{eq:classification} gives the
critical intensity.

We work with the unsplit binary tree, giving conductance
$c_n=L_n^{-1}$ to each edge between generations $n$ and $n+1$.
Its cable tree is proper since every cable has length at least
$1/2$, and subdivision leaves the cable tree unchanged.
The equally splitting unit flow has energy $V_0<\infty$ and
potential at generation $n$ given by
\begin{equation}
 V_n=\sum_{k=n}^\infty\frac{L_k}{2^{k+1}}
     \asymp\frac1{n+1}.
 \label{eq:zero-threshold-potential}
\end{equation}
Indeed, the ceiling in \eqref{eq:zero-threshold-lengths} changes this
tail by at most $2^{-n}$. In particular, the network is transient.
Writing $h_n=V_n/V_0$, the transformed conductances satisfy
\begin{equation}
 \widehat c_n=L_n^{-1}h_nh_{n+1}\asymp2^{-n}.
 \label{eq:zero-threshold-transform}
\end{equation}
Equation~\eqref{eq:green-resistance} therefore gives
\begin{equation}
 \rho_n^{-2}=1+\frac1{V_0}\sum_{k=0}^{n-1}\widehat c_k^{-1}
       \asymp2^n.
 \label{eq:zero-threshold-correlation}
\end{equation}
Since $N_n=2^n$, the spherical formula \eqref{eq:spherical-cutsets}
yields $D_G=2$. The classification and skeleton invariance in
Theorem~\ref{thm:classification} prove \eqref{eq:zero-threshold}.

\label{prop:ray-capacity}
For every $\xi\in\partial T$ and $n\ge1$,
\begin{equation}
 \operatorname{cap}([o,\xi_n])=\sum_{j=0}^{n-1}s_j(\xi)+C_{\xi_n}^+.
 \label{eq:segment-capacity}
\end{equation}
Consequently \eqref{eq:capacity-condition} is equivalent to divergence
of the right-hand side of \eqref{eq:segment-capacity} along every
infinite ray. If all conductances are one, this is equivalent to
\begin{equation}
 \sum_{n\ge0}s_n(\xi)=\infty\qquad(\xi\in\partial T).
 \label{eq:ray-capacity-condition}
\end{equation}

\label{lem:pruning}
The tree $T^\infty$, with its inherited conductances, is transient,
its cable metric is proper, and
\begin{equation}
 g_T(x,y)=g_{T^\infty}(x,y)\quad(x,y\in T^\infty),\qquad
 D_G(T)=D_G(T^\infty).
 \label{eq:pruning}
\end{equation}
Capacities of finite subsets of $T^\infty$ agree in both networks.
Condition~\eqref{eq:capacity-condition} holds on $T$ if and only if
it holds on $T^\infty$.

\label{prop:degree}
Assume \eqref{eq:capacity-condition}. If there are $\kappa\ge0$
and $0<A<\infty$ such that
\begin{equation}
 \Lambda(x)\le A\theta(x)^{-\kappa}
             \qquad(x\ne o,\ \theta(x)>0),
 \label{eq:conductance-assumption}
\end{equation}
then
\begin{equation}
 D_G(T)\ge\frac2{2+\kappa},\qquad
 \frac12\le\widetilde\alpha_{\mathsf c}(T)\le\frac{1+\kappa}{2+\kappa}.
 \label{eq:degree-conclusion}
\end{equation}
For unit conductances it suffices that
\begin{equation}
 \deg_T(x)\le A\theta(x)^{-\kappa}
             \qquad(x\ne o,\ \theta(x)>0).
 \label{eq:degree-assumption}
\end{equation}
If \eqref{eq:conductance-assumption} holds for every $\kappa>0$,
with $A$ depending on $\kappa$, then $\widetilde\alpha_{\mathsf c}(T)=1/2$.

Use the notation in \eqref{eq:symmetric-parameters}.
Symmetry gives $\theta(x)=N_n^{-1}$ at depth $n$.
Equation \eqref{eq:current} yields
$\rho_o(x)=\rho_n\asymp(N_n\sqrt{b_n})^{-1}$, uniformly in $n\ge1$.
Equation~\eqref{eq:spherical-cutsets} now gives
\begin{equation}
 D_G=\liminf_n\frac{\log N_n}{-\log\rho_n}
 =\liminf_n\frac{\log N_n}
                  {\log N_n+\frac12\log b_n+O(1)}
 =\frac2{2+r}.
 \label{eq:symmetric-exponent}
\end{equation}
Equation~\eqref{eq:classification} now gives \eqref{eq:symmetric}.

\label{lem:terminal}
There is an $\mathcal F_x$-measurable $U_x\in[0,1]$ such that
\begin{equation}
 U_xW_x\le\theta_T(x)\le U_x.
 \label{eq:conditional-flow-comparison}
\end{equation}
In particular, if $\kappa=\mathbf E_\infty W>0$, then, for every
$A\subseteq\{1,2,\ldots\}$ and $n\ge1$,
\begin{equation}
 \mathbf E_\infty\sum_{|x|=n}\theta_T(x)\mathbf 1_{\{Y_x\in A\}}
       \le\kappa^{-1}\mathbf P_\infty(Y\in A).
 \label{eq:harmonic-domination}
\end{equation}

\label{lem:harmonic-decay}
There is a deterministic $c>0$, depending only on the law of $Y$,
such that almost surely
\begin{equation}
 \max_{|x|=n}\theta_T(x)\le e^{-cn}
       \quad\text{for all sufficiently large }n.
 \label{eq:harmonic-decay}
\end{equation}

For an ordinary descendant tree with $Y$ children, let $W_i$ be
the conductance through its $i$th child, including the initial unit
edge, and put
\begin{equation}
 B=\sum_{i=1}^Y\left(\frac{W_i}{C}\right)^2,
 \qquad C=\sum_{i=1}^YW_i,\qquad
 \delta=\mathbf E_\infty[W^2(1-B)].
 \label{eq:split-loss}
\end{equation}
Every $W_i$ is positive. Hence $B\le1$, with strict inequality when
$Y\ge2$, and $0<\delta<1$. At a nonroot vertex $x$, let $B_x$
be the corresponding sum of squared current fractions to its children.
By \eqref{eq:conditional-flow-comparison} and independence from $\mathcal F_x$,
\begin{align}
 \mathbf E_\infty[\theta_T(x)^2(1-B_x)\mid\mathcal F_x]
 &\ge U_x^2\mathbf E_\infty[W^2(1-B)]\nonumber\\
 &=\delta U_x^2
 \ge\delta\mathbf E_\infty[\theta_T(x)^2\mid\mathcal F_x].
 \label{eq:conditional-loss}
\end{align}
Let $H_n=\sum_{|x|=n}\theta_T(x)^2$. The identity
$H_{n+1}=\sum_{|x|=n}\theta_T(x)^2B_x$ and
\eqref{eq:conditional-loss} imply
\begin{equation}
 \mathbf E_\infty H_{n+1}\le(1-\delta)\mathbf E_\infty H_n\quad(n\ge1),\qquad
 \mathbf E_\infty H_n\le(1-\delta)^{n-1},
 \label{eq:flow-second-moment}
\end{equation}
since $H_1\le1$. No moment of the root law is used. Choose $c>0$
with $e^{2c}(1-\delta)<1$. Markov's inequality gives
\begin{equation}
 \mathbf P_\infty\{\max_{|x|=n}\theta_T(x)>e^{-cn}\}
 \le e^{2cn}(1-\delta)^{n-1}.
 \label{eq:flow-tail}
\end{equation}
The right-hand side is summable, so Borel--Cantelli proves the claim.

\label{prop:finite-log}
If $\mathbf E_\infty\log(Y+1)<\infty$, then $D_G(T)=1$ for
$\mathbf P_\infty$-almost every tree.

\label{prop:truncated-bound}
For every $M$ with $m_M>1$, almost surely
\begin{equation}
 D_G(T)\ge\frac{\log m_M}{\log(M+1)}.
 \label{eq:truncated-bound}
\end{equation}
